  // Retire pending replies and clear the old range when segment zero changes.
  void updateSelection() {
    uint16_t start = 0, stop = 0;
    if (strip.getSegmentsNum()) {
      const Segment& first = strip.getSegment(0);
      start = std::min<uint16_t>(first.start, strip.getLengthTotal());
      stop = std::min<uint16_t>(first.stop, strip.getLengthTotal());
      if (stop < start) stop = start;
    }
    if (!selectionChanged && start == segmentStart && stop == segmentStop) return;
    // Clear the previous range once so shrinking leaves no stale lamps.
    if (ownsLeds && !realtimeOverride) {
      for (uint16_t pixel = segmentStart; pixel < segmentStop && pixel < strip.getLengthTotal(); pixel++)
        strip.setPixelColor(pixel, 0);
      strip.show();
    }
    segmentStart = start;
    segmentStop = stop;
    segmentCapacity.store(stop - start - (start == KiteWindStatus::STATUS_PIXEL && stop > start ? 1 : 0));
    selectionChanged = false;
    invalidate();
  }

